										// =====================================================
										is_tool_item = false;
										if(input.Item != null && input.Item.Is_Tool == true)
										{
											is_tool_item = true;
										}
										// a sold or transferred tool is not Borrowed
										if(is_tool_item == true && input.Request_Voucher_Type != "Internal Transfer" && input.Request_Voucher_Type != "Sales Voucher")
										{
											input.Status = "Borrowed";
										}
										else
										{
											input.Status = "Issued";
											input.Expected_Return_Date = null;
										}
										// =====================================================
										// 10) ISSUE STOCK IN STORE MANAGEMENT
										// =====================================================
										stock_resp = store_management.stock.issue_stock_from_freedomArena(input.Item,store_id,input.Quantity,input.Unit_Of_Measure,cond,line_total_val,ref_no,input.ID);
										info stock_resp;
										if(stock_resp == null || stock_resp.get("ok") != true)
										{
											input.Status = "Draft";
											info "Stock issue failed: " + ifnull(stock_resp.get("message"),"No response from Store Management.");
											return;
										}
										// =====================================================
										// 11) UPDATE STOCK PREVIEW FROM RESPONSE
										// =====================================================
										input.Quantity_in_Base_Unit_Of_Measure = ifnull(stock_resp.get("base_qty"),base_qty);
										input.Store_Available_Stock = ifnull(stock_resp.get("store_stock"),0.0);
										input.Global_Available_Stock = ifnull(stock_resp.get("global_stock"),0.0);
										// =====================================================
										// 12) UPDATE SALES VOUCHER DETAILS ISSUE STATUS
										// =====================================================
										if(input.Request_Voucher_Type == "Sales Voucher" && input.Item_Taken != null)
										{
											svd = Sales_Voucher_Details[ID == input.Item_Taken];
											if(svd.ID != null)
											{
												total_issued_base = 0.0;
												for each  issue in Item_Issuing_Details[Item_Taken == svd.ID]
												{
													total_issued_base = total_issued_base + ifnull(issue.Quantity_in_Base_Unit_Of_Measure,0.0);
												}
												required_base = ifnull(svd.Quantity_in_Base_Unit_Of_Measure,0.0);
												svd.Quantity_Issued_in_Base_Unit_Of_Measure=total_issued_base;
												not_issued_base = required_base - total_issued_base;
												if(not_issued_base < 0)
												{
													not_issued_base = 0.0;
												}
												svd.Quantity_Not_Issued_in_Base_Unit_Of_Measure=not_issued_base;
												if(total_issued_base <= 0)
												{
													svd.Issue_Status="Not Issued";
												}
												else if(total_issued_base >= required_base)
												{
													svd.Issue_Status="Fully Issued";
												}
												else
												{
													svd.Issue_Status="Partially Issued";
												}
											}
										}
										// =====================================================
										// 13) CREATE / UPDATE EMPLOYEE ISSUING DETAILS
										// =====================================================
										source_form_val = "Item Issuing Details";
										if(input.Request_Voucher_Type == "Employee Voucher" && input.Employee_Voucher != null)
										{
											existing_eid = Employee_Issuing_Details[Source_Record_ID == input.ID && Source_Form == source_form_val];
											if(existing_eid.ID != null)
											{
												existing_eid.Voucher=input.Employee_Voucher;
												existing_eid.Display_Name_Voucher=input.Request_Voucher;
												existing_eid.Line_Number=input.Line_Number;
												existing_eid.Display_Name_Item=input.Display_Name_Item;
												existing_eid.Quantity=input.Quantity;
												existing_eid.Cost=input.Cost;
												existing_eid.Item_Issuing_Detail=input.Item_Issuing_Number;
												existing_eid.Source_Record_ID=input.ID;
												existing_eid.Source_Form=source_form_val;
											}
											else
											{
												insert into Employee_Issuing_Details
												[
													Voucher=input.Employee_Voucher
													Display_Name_Voucher=input.Request_Voucher
													Line_Number=input.Line_Number
													Display_Name_Item=input.Display_Name_Item
													Quantity=input.Quantity
													Cost=input.Cost
													Item_Issuing_Detail=input.Item_Issuing_Number
													Source_Record_ID=input.ID
													Source_Form=source_form_val
													Added_User=zoho.loginuser
												]
											}
										}
										// =====================================================
										// 14) CREATE / UPDATE VOUCHER ISSUING DETAILS
										// =====================================================
										if(input.Issuing_Voucher != null)
										{
											voucher_id = null;
											voucher_display = "";
											iiv = Item_Issuing_Voucher[ID == input.Issuing_Voucher];
											if(iiv.ID != null)
											{
												voucher_id = iiv.Item_Issuing_Voucher;
												voucher_display = ifnull(iiv.Display_Name_Item_Issuing_Voucher,"").trim();
												if(voucher_display == "" && iiv.Item_Issuing_Voucher != null)
												{
													voucher_display = ifnull(iiv.Item_Issuing_Voucher.Voucher_Number,"");
												}
											}
											if(voucher_id != null)
											{
												existing_vid = Voucher_Issuing_Details[Source_Record_ID == input.ID && Source_Form == source_form_val];
												if(existing_vid.ID != null)
												{
													existing_vid.Voucher=voucher_id;
													existing_vid.Display_Name_Voucher=voucher_display;
													existing_vid.Line_Number=input.Line_Number;
													existing_vid.Display_Name_Item=input.Display_Name_Item;
													existing_vid.Quantity=input.Quantity;
													existing_vid.Cost=input.Cost;
													existing_vid.Item_Issuing_Detail=input.Item_Issuing_Number;
													existing_vid.Source_Record_ID=input.ID;
													existing_vid.Source_Form=source_form_val;
												}
												else
												{
													insert into Voucher_Issuing_Details
													[
														Voucher=voucher_id
														Display_Name_Voucher=voucher_display
														Line_Number=input.Line_Number
														Display_Name_Item=input.Display_Name_Item
														Quantity=input.Quantity
														Cost=input.Cost
														Item_Issuing_Detail=input.Item_Issuing_Number
														Source_Record_ID=input.ID
														Source_Form=source_form_val
														Added_User=zoho.loginuser
													]
												}
											}
										}
										// =====================================================
										// 15) DONE
										// =====================================================
										info "Item Issuing Details finalized on create. Final Status = " + input.Status;

// =====================================================
										// ITEM ISSUING DETAILS - FINALIZE ON EDIT
										// =====================================================
										// 1) LOAD SAVED RECORD
										saved_rec = Item_Issuing_Details[ID == input.ID];
										if(saved_rec.ID == null)
										{
											info "Saved Item Issuing Details not found.";
											return;
										}
										saved_status = ifnull(saved_rec.Status,"").trim();
										current_status = ifnull(input.Status,"").trim();
										// 2) EDIT AUDIT
										u = thisapp.audit.getLoginAuditInfo();
										input.Updated_By_Name = u.get("name");
										input.Updated_By_Email = u.get("email");
										input.Updated_By_Time = zoho.currenttime;
										// 3) CANCEL LINE
										if(input.Cancel_This_Line_Item == true)
										{
											input.Status = "Cancelled";
											info "Line item cancelled. No stock change.";
											return;
										}
										// 4) PRESERVE IMPORTANT FIELDS
										if(input.Item == null)
										{
											input.Item = saved_rec.Item;
										}
										if(input.Display_Name_Item == null || input.Display_Name_Item.trim() == "")
										{
											input.Display_Name_Item = saved_rec.Display_Name_Item;
										}
										if(input.Unit_Of_Measure == null)
										{
											input.Unit_Of_Measure = saved_rec.Unit_Of_Measure;
										}
										if(input.Display_Name_Unit_Of_Measure == null || input.Display_Name_Unit_Of_Measure.trim() == "")
										{
											input.Display_Name_Unit_Of_Measure = saved_rec.Display_Name_Unit_Of_Measure;
										}
										if(input.Quantity == null)
										{
											input.Quantity = saved_rec.Quantity;
										}
										if(input.Cost == null)
										{
											input.Cost = ifnull(saved_rec.Cost,0.0);
										}
										if(input.Stock_Condition == null || input.Stock_Condition.trim() == "")
										{
											input.Stock_Condition = ifnull(saved_rec.Stock_Condition,"New");
										}
										if(input.Request_Voucher_Type == null || input.Request_Voucher_Type.trim() == "")
										{
											input.Request_Voucher_Type = ifnull(saved_rec.Request_Voucher_Type,"");
										}
										if(input.Employee_Voucher == null)
										{
											input.Employee_Voucher = saved_rec.Employee_Voucher;
										}
										if(input.Work_Order_Task == null)
										{
											input.Work_Order_Task = saved_rec.Work_Order_Task;
										}
										if(input.Line_Number == null)
										{
											input.Line_Number = saved_rec.Line_Number;
										}
										if(input.Item_Issuing_Number == null || input.Item_Issuing_Number.trim() == "")
										{
											input.Item_Issuing_Number = saved_rec.Item_Issuing_Number;
										}
										if(input.Quantity_Returned == null)
										{
											input.Quantity_Returned = ifnull(saved_rec.Quantity_Returned,0.0);
										}
										if(input.Quantity_Returned_in_Base_Unit_Of_Measure == null)
										{
											input.Quantity_Returned_in_Base_Unit_Of_Measure = ifnull(saved_rec.Quantity_Returned_in_Base_Unit_Of_Measure,0.0);
										}
										// 5) NON-EMPLOYEE VOUCHER TYPES
										if(input.Request_Voucher_Type != "Employee Voucher")
										{
											if(current_status == "Draft" || current_status == "")
											{
												input.Status = "Approved";
												info "Draft moved to Approved. No stock deducted.";
												return;
											}
											if(current_status == "Approved")
											{
												input.Status = "Issued";
												current_status = "Issued";
											}
											else if(current_status != "Issued")
											{
												info "No activities run. Status is " + current_status;
												return;
											}
											if(input.Issuing_Voucher == null)
											{
												info "Issuing Voucher is required.";
												return;
											}
											if(input.Item == null || input.Unit_Of_Measure == null || input.Quantity == null || input.Quantity <= 0)
											{
												info "Item, Unit of Measure and Quantity are required.";
												return;
											}
											hdr = Item_Issuing_Voucher[ID == input.Issuing_Voucher];
											if(hdr.ID == null || hdr.Store == null)
											{
												info "Header missing or Store missing.";
												return;
											}
											store_id = hdr.Store;
											cond = ifnull(input.Stock_Condition,"New").trim();
											if(cond == "")
											{
												cond = "New";
												input.Stock_Condition = "New";
											}
											check = store_management.po.check_uom_conversion_from_masaka_site_management(input.Item,input.Unit_Of_Measure);
											if(check == null || check.get("ok") != true)
											{
												info ifnull(check.get("message"),"UOM conversion failed.");
												return;
											}
											base_qty_create = store_management.po.convert_to_base_qty_from_masaka_site_management(input.Item,input.Unit_Of_Measure,input.Quantity);
											if(base_qty_create == null || base_qty_create <= 0)
											{
												info "Invalid base quantity.";
												return;
											}
											input.Quantity_in_Base_Unit_Of_Measure = base_qty_create;
											line_total_val = (base_qty_create * ifnull(input.Cost,0.0)).round(2);
											input.Line_Total = line_total_val;
											// Deduct stock only when moving Approved -> Issued
											if(saved_status == "Approved" && input.Status == "Issued")
											{
												ref_no = ifnull(hdr.Display_Name_Item_Issuing_Voucher,"").trim();
												if(ref_no == "")
												{
													ref_no = hdr.ID.toString();
												}
												stock_resp = store_management.stock.issue_stock_from_freedomArena(input.Item,store_id,input.Quantity,input.Unit_Of_Measure,cond,line_total_val,ref_no,input.ID);
												info stock_resp;
												if(stock_resp == null || stock_resp.get("ok") != true)
												{
													input.Status = saved_status;
													info "Stock issue failed: " + ifnull(stock_resp.get("message"),"No response from Store Management.");
													return;
												}
												input.Quantity_in_Base_Unit_Of_Measure = ifnull(stock_resp.get("base_qty"),base_qty_create);
												input.Store_Available_Stock = ifnull(stock_resp.get("store_stock"),0.0);
												input.Global_Available_Stock = ifnull(stock_resp.get("global_stock"),0.0);
											}
											else
											{
												info "No stock deduction. Stock only deducts when saved status is Approved and final status becomes Issued.";
											}
											if(input.Request_Voucher_Type == "Work Order Task" && input.Work_Order_Task != null)
											{
												qty_selected = ifnull(input.Quantity,0.0);
												qty_base = ifnull(input.Quantity_in_Base_Unit_Of_Measure,0.0);
												line_total_val = ifnull(input.Line_Total,0.0);
												unit_cost_selected = ifnull(input.Cost,0.0);
												rate_base = 0.0;
												if(qty_base > 0 && line_total_val > 0)
												{
													rate_base = (line_total_val / qty_base).round(2);
												}
												pc_exists = false;
												for each  pc_chk in Parts_Consumables[Source_Record_ID == input.ID && Source_Form == "Item Issuing Details"]
												{
													pc_exists = true;
													pc_chk.Work_Order_Task_Number=input.Work_Order_Task;
													pc_chk.Display_Name_Work_Order_Task_Number=ifnull(input.Work_Order_Task.Work_Order_Task_Number,"");
													pc_chk.Line_Number=input.Line_Number;
													pc_chk.Item=input.Item;
													pc_chk.Display_Name_Item_Labour=ifnull(input.Display_Name_Item,"");
													pc_chk.Quantity=qty_selected;
													pc_chk.Quantity_In_Base_Unit=qty_base;
													pc_chk.Unit_Of_Measure=ifnull(input.Display_Name_Unit_Of_Measure,"");
													pc_chk.Unit_Cost=unit_cost_selected;
													pc_chk.Rate_In_Base_Unit=rate_base;
													pc_chk.Line_Total=line_total_val;
													pc_chk.Item_Issuing_Detail=input.Item_Issuing_Number;
													pc_chk.Item_Status=input.Status;
													break;
												}
												if(pc_exists == false)
												{
													insert into Parts_Consumables
													[
														Work_Order_Task_Number=input.Work_Order_Task
														Display_Name_Work_Order_Task_Number=ifnull(input.Work_Order_Task.Work_Order_Task_Number,"")
														Line_Number=input.Line_Number
														Item=input.Item
														Display_Name_Item_Labour=ifnull(input.Display_Name_Item,"")
														Quantity=qty_selected
														Quantity_In_Base_Unit=qty_base
														Unit_Of_Measure=ifnull(input.Display_Name_Unit_Of_Measure,"")
														Unit_Cost=unit_cost_selected
														Rate_In_Base_Unit=rate_base
														Line_Total=line_total_val
														Item_Issuing_Detail=input.Item_Issuing_Number
														Item_Status=input.Status
														Source_Record_ID=input.ID.toString()
														Source_Form="Item Issuing Details"
														Added_User=zoho.loginuser
													]
												}
											}
											info "Masaka non-employee request finalized. Final status = " + input.Status;
											return;
										}
										// 6) EMPLOYEE VOUCHER REQUIRED FIELDS
										if(input.Issuing_Voucher == null)
										{
											info "Issuing Voucher is required.";
											return;
										}
										if(input.Employee_Voucher == null)
										{
											info "Employee Voucher is required.";
											return;
										}
										if(input.Item == null || input.Unit_Of_Measure == null || input.Quantity == null || input.Quantity <= 0)
										{
											info "Item, Unit of Measure and Quantity are required.";
											return;
										}
										// 7) LOAD ISSUING HEADER + STORE
										hdr = Item_Issuing_Voucher[ID == input.Issuing_Voucher];
										if(hdr.ID == null || hdr.Store == null)
										{
											info "Header missing or Store missing.";
											return;
										}
										store_id = hdr.Store;
										// 8) STOCK CONDITION
										cond = ifnull(input.Stock_Condition,"New").trim();
										if(cond == "")
										{
											cond = "New";
											input.Stock_Condition = "New";
										}
										// 9) UOM CHECK + BASE QUANTITY
										check = store_management.po.check_uom_conversion_from_masaka_site_management(input.Item,input.Unit_Of_Measure);
										if(check == null || check.get("ok") != true)
										{
											info ifnull(check.get("message"),"UOM conversion failed.");
											return;
										}
										base_qty = store_management.po.convert_to_base_qty_from_masaka_site_management(input.Item,input.Unit_Of_Measure,input.Quantity);
										if(base_qty == null || base_qty <= 0)
										{
											info "Invalid base quantity.";
											return;
										}
										input.Quantity_in_Base_Unit_Of_Measure = base_qty;
										// 10) LINE TOTAL
										line_total_val = (base_qty * ifnull(input.Cost,0.0)).round(2);
										input.Line_Total = line_total_val;
										// 11) TOOL CHECK + FINAL STATUS
										is_tool_item = false;
										if(input.Item != null && input.Item.Is_Tool == true)
										{
											is_tool_item = true;
										}
										if(is_tool_item == true)
										{
											if(input.Didn_t_Come_Back == true)
											{
												input.Status = "Out of Service";
												input.Expected_Return_Date = null;
											}
											else
											{
												issued_base = ifnull(input.Quantity_in_Base_Unit_Of_Measure,0.0);
												returned_base = ifnull(input.Quantity_Returned_in_Base_Unit_Of_Measure,0.0);
												if(issued_base > 0 && returned_base >= issued_base)
												{
													input.Status = "Returned";
													input.Expected_Return_Date = null;
												}
												else
												{
													input.Status = "Borrowed";
												}
											}
										}
										else
										{
											input.Status = "Issued";
											input.Expected_Return_Date = null;
										}
										// 12) REFERENCE NUMBER
										ref_no = ifnull(hdr.Display_Name_Item_Issuing_Voucher,"").trim();
										if(ref_no == "")
										{
											ref_no = hdr.ID.toString();
										}
										// 13) ISSUE STOCK IN STORE MANAGEMENT
										stock_resp = store_management.stock.issue_stock_from_freedomArena(input.Item,store_id,input.Quantity,input.Unit_Of_Measure,cond,line_total_val,ref_no,input.ID);
										info stock_resp;
										if(stock_resp == null || stock_resp.get("ok") != true)
										{
											input.Status = saved_status;
											info "Stock issue failed: " + ifnull(stock_resp.get("message"),"No response from Store Management.");
											return;
										}
										// 14) UPDATE STOCK PREVIEW FROM RESPONSE
										input.Quantity_in_Base_Unit_Of_Measure = ifnull(stock_resp.get("base_qty"),base_qty);
										input.Store_Available_Stock = ifnull(stock_resp.get("store_stock"),0.0);
										input.Global_Available_Stock = ifnull(stock_resp.get("global_stock"),0.0);
										// 15) LOCAL EMPLOYEE ISSUING DETAILS
										if(input.Employee_Voucher != null)
										{
											eid_exists = false;
											for each  e_chk in Employee_Issuing_Details[Source_Record_ID == input.ID && Source_Form == "Item Issuing Details"]
											{
												eid_exists = true;
												e_chk.Voucher=input.Employee_Voucher;
												e_chk.Display_Name_Voucher=input.Request_Voucher;
												e_chk.Line_Number=input.Line_Number;
												e_chk.Display_Name_Item=input.Display_Name_Item;
												e_chk.Quantity=input.Quantity;
												e_chk.Cost=input.Cost;
												e_chk.Item_Issuing_Detail=input.Item_Issuing_Number;
												break;
											}
											if(eid_exists == false)
											{
												insert into Employee_Issuing_Details
												[
													Voucher=input.Employee_Voucher
													Display_Name_Voucher=input.Request_Voucher
													Line_Number=input.Line_Number
													Display_Name_Item=input.Display_Name_Item
													Quantity=input.Quantity
													Cost=input.Cost
													Item_Issuing_Detail=input.Item_Issuing_Number
													Source_Record_ID=input.ID
													Source_Form="Item Issuing Details"
													Added_User=zoho.loginuser
												]
											}
										}
										// 16) DONE
										info "Freedom City Arena Item Issuing Details finalized on edit. Final status = " + input.Status;

// =============================================
										// Item Issuing Details -> Set Up Form
