										// Hide display/helper fields
										// =============================================
										hide Display_Name_Issuing_Voucher;
										hide Display_Name_Item;
										hide Display_Name_Taken_By;
										hide Display_Name_Unit_Of_Measure;
										hide Quantity_Returned;
										hide Quantity_Returned_in_Base_Unit_Of_Measure;
										hide Display_Name_Issued_By;
										hide Status;
										hide Notes;
										hide Status_Details;
