												po_det_status.Quantity_Remaining=qty_remaining;
												if(total_received <= 0)
												{
													po_det_status.Receiving_Status="Not Received";
												}
												else if(qty_remaining > 0)
												{
													po_det_status.Receiving_Status="Partially Received";
												}
												else
												{
													po_det_status.Receiving_Status="Fully Received";
												}
												po_det_status.Quantity_Billable=total_received;
												po_det_status.Quantity_Unbilled=total_received - ifnull(po_det_status.Quantity_Billed,0.0);
												if(po_det_status.Quantity_Unbilled < 0)
												{
													po_det_status.Quantity_Unbilled=0.0;
												}
												if(po_det_status.Purchase_Order != null)
